import { useState } from 'react';
import { JxTable, JxPagination, JxBadge } from '@jinx-ui/react';

interface User {
  id: string;
  name: string;
  role: string;
  active: boolean;
}

interface UsersTableProps {
  users: User[];
}

const PAGE_SIZE = 10;

export default function UsersTable({ users }: UsersTableProps) {
  const [page, setPage] = useState(1);
  const pageCount = Math.ceil(users.length / PAGE_SIZE);
  const visible = users.slice((page - 1) * PAGE_SIZE, page * PAGE_SIZE);

  return (
    <div>
      <JxTable>
        <thead>
          <tr>
            <th>Имя</th>
            <th>Роль</th>
            <th>Статус</th>
          </tr>
        </thead>
        <tbody>
          {visible.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <JxBadge tone={user.active ? 'success' : 'default'} dot>
                  {user.active ? 'Активен' : 'Отключён'}
                </JxBadge>
              </td>
            </tr>
          ))}
        </tbody>
      </JxTable>
      {pageCount > 1 && (
        <JxPagination total={pageCount} page={page} onPageChange={setPage} />
      )}
    </div>
  );
}

